var createShuffleQueue = (songs) => {
  let queue = Array.from(songs.keys());
  for (let i = queue.length - 1; i > 0; i--) {
    let j = Math.floor(Math.random() * (i + 1));
    [queue[i], queue[j]] = [queue[j], queue[i]];
  }
  return queue;
}, createShuffleQueue_default = createShuffleQueue;

